const payload = $json.body ?? {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const isStringArray = (value) => Array.isArray(value) && value.every((item) => typeof item === 'string' && item.length <= 320);
const tones = {
  formel: 'Rédige une réponse formelle, courtoise et structurée.',
  neutre: 'Rédige une réponse professionnelle, claire et naturelle.',
  court: 'Rédige une réponse très concise et directement utile.'
};
const validMessages = Array.isArray(payload.messages) && payload.messages.length > 0 && payload.messages.length <= 100 && payload.messages.every((message) =>
  message &&
  uuid.test(message.email_id ?? '') &&
  typeof message.sender === 'string' && message.sender.length <= 320 &&
  isStringArray(message.recipients) &&
  typeof message.subject === 'string' && message.subject.length <= 998 &&
  typeof message.body === 'string' && message.body.length <= 100000 &&
  typeof message.received_at === 'string' && !Number.isNaN(Date.parse(message.received_at))
);
const totalBodyLength = Array.isArray(payload.messages)
  ? payload.messages.reduce((total, message) => total + (typeof message?.body === 'string' ? message.body.length : 0), 0)
  : 0;
const valid =
  uuid.test(payload.generation_id ?? '') &&
  uuid.test(payload.user_id ?? '') &&
  uuid.test(payload.email_id ?? '') &&
  uuid.test(payload.thread_id ?? '') &&
  typeof payload.gmail_thread_id === 'string' && payload.gmail_thread_id.length > 0 && payload.gmail_thread_id.length <= 255 &&
  typeof payload.subject === 'string' && payload.subject.length <= 998 &&
  isStringArray(payload.recipients) &&
  isStringArray(payload.reply_to) &&
  Object.hasOwn(tones, payload.tone) &&
  validMessages &&
  totalBodyLength <= 200000;

if (!valid) {
  return [{ json: {
    valid: false,
    generation_id: payload.generation_id ?? '',
    user_id: payload.user_id ?? '',
    email_id: payload.email_id ?? '',
    error_message: 'Payload de génération invalide.'
  } }];
}

const context = {
  subject: payload.subject,
  recipients: payload.recipients,
  reply_to: payload.reply_to,
  messages: payload.messages
};
return [{ json: {
  valid: true,
  generation_id: payload.generation_id,
  user_id: payload.user_id,
  email_id: payload.email_id,
  tone: payload.tone,
  tone_instruction: tones[payload.tone],
  context_json: JSON.stringify(context)
} }];

