const request = $('Valider payload').item.json;
const generated = typeof $json.text === 'string' ? $json.text.trim() : '';
const modelFailed = typeof $json.error === 'string' && $json.error.length > 0;
const valid = !modelFailed && generated.length > 0 && generated.length <= 100000 && !generated.includes('\u0000');
return [{ json: {
  valid,
  generation_id: request.generation_id,
  user_id: request.user_id,
  email_id: request.email_id,
  body_text: valid ? generated : undefined,
  error_message: valid ? undefined : (modelFailed
    ? 'La génération Gemini a échoué après les tentatives autorisées.'
    : 'Le contenu généré est vide ou invalide.')
} }];

return [{ json: {
  generation_id: $json.generation_id,
  user_id: $json.user_id,
  email_id: $json.email_id,
  status: 'ready',
  body_text: $json.body_text
} }];

return [{ json: {
  generation_id: $json.generation_id,
  user_id: $json.user_id,
  email_id: $json.email_id,
  status: 'failed',
  error_message: String($json.error_message || 'La génération du brouillon a échoué.').slice(0, 2000)
} }];
